frontend/dist/testcenter-frontend/browser/chunk-2MCW35IL.js.map:4:  "sourcesContent": ["import { Injectable, Inject } from '@angular/core';
import { HttpClient, HttpResponse } from '@angular/common/http';
import { Observable } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { SysCheckInfo, AuthData, AppError, Challenge } from './app.interfaces';
import { SysConfig } from './shared/shared.module';

@Injectable({
  providedIn: 'root'
})
export class BackendService {
  constructor(@Inject('BACKEND_URL') private readonly serverUrl: string, private http: HttpClient) { }

  createChallenge(
    challenge: { loginType: 'admin' | 'login', name: string, password: string } | { code: string }
  ): Observable<Challenge>
  {
    return this.http.post<Challenge>(this.serverUrl + 'session' + ('loginType' in challenge ? '':'/person'), challenge);
  }

  createSession(
    algorithm: Challenge['algorithm'],
    challenge: Challenge['challenge'],
    salt: Challenge['salt'],
    signature: Challenge['signature'],
    number: number
  ): Observable<AuthData> {
    return this.http.put<AuthData>(`${this.serverUrl}session`, { algorithm, challenge, salt, signature, number });
  }

  adminLogin(name: string, password: string | undefined = undefined): Observable<AuthData> {
    return this.http.put<AuthData>(`${this.serverUrl}session/admin`, { name, password });
  }

  login(name: string, password?: string): Observable<AuthData> {
    return this.http.put<AuthData>(`${this.serverUrl}session/login`, { name, password });
  }

  codeLogin(code: string): Observable<AuthData> {
    return this.http.put<AuthData>(`${this.serverUrl}session/person`, { code });
  }

  getSessionData(): Observable<AuthData> {
    return this.http.get<AuthData>(`${this.serverUrl}session`);
  }

  startTest(bookletName: string): Observable<number> {
    return this.http
      .put<number>(`${this.serverUrl}test`, { bookletName });
  }

  getSysConfig(): Observable<SysConfig> {
    return this.http
      .get<SysConfig>(`${this.serverUrl}system/config`)
      .pipe(
        catchError((error: AppError) => {
          if (error.code !== 503) {
            error.type = 'fatal';
          }
          throw error;
        })
      );
  }

  checkIfSysCheckModeExists(): Observable<boolean> {
    return this.http
      .get<boolean>(`${this.serverUrl}sys-check-mode`);
  }

  getSysCheckInfosAcrossWorkspaces(): Observable<SysCheckInfo[]> {
    return this.http
      .get<SysCheckInfo[]>(`${this.serverUrl}sys-checks`);
  }

  downloadReviews(): Observable<HttpResponse<Blob>> {
    return this.http.get(`${this.serverUrl}reviews/export`, {
      headers: {
        Accept: 'text/csv'
      },
      responseType: 'blob',
      observe: 'response'
    });
  }
}
